\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segDocs | segXmd
\end{zed}

\begin{zed}
RAWSEG ::= rsSeg \ldata SEG \rdata | rsEmpty | rsDot
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{axdef}
unwrap : RAWSEG \pfun SEG
\where
\dom unwrap = \ran rsSeg \\
\forall s : SEG @ unwrap(rsSeg(s)) = s
\end{axdef}

\begin{axdef}
witnessPattern : \seq PATSEG
\where
witnessPattern = \langle litSeg(segDocs), wildRestSeg \rangle
\end{axdef}

\begin{schema}{FileRaw}
raw : \seq RAWSEG \\
segs : \seq SEG \\
absolute : ZBOOL \\
covered : ZBOOL
\where
\# raw \leq maxSegs \\
segs = squash(raw \comp unwrap) \\
absolute = (\IF \# raw > 0 \land raw(1) = rsEmpty \THEN ztrue \ELSE zfalse) \\
covered = (\IF \# segs \geq 1 \land segs(1) = segDocs \THEN ztrue \ELSE zfalse)
\end{schema}

\begin{schema}{Init}
FileRaw'
\end{schema}

\begin{schema}{Idle}
\Xi FileRaw
\where
\lnot (absolute = ztrue \land covered = ztrue)
\end{schema}

\end{document}

