\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segDocs | segFile | segStarStar
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{axdef}
Stringify : PATSEG \fun SEG
\where
Stringify(wildRestSeg) = segStarStar \\
\forall s : SEG @ Stringify(litSeg(s)) = s
\end{axdef}

\begin{axdef}
witnessEntry : \seq PATSEG
\where
witnessEntry = \langle litSeg(segDocs), wildRestSeg \rangle
\end{axdef}

\begin{axdef}
witnessEntryIsDir : ZBOOL
\where
witnessEntryIsDir = zfalse
\end{axdef}

\begin{schema}{FileSegs}
segs : \seq SEG \\
semanticCovered : ZBOOL \\
literalCovered : ZBOOL
\where
\# segs \leq maxSegs \\
semanticCovered = (\IF \# segs \geq 1 \land segs(1) = segDocs \THEN ztrue \ELSE zfalse) \\
literalCovered = (\IF witnessEntryIsDir = ztrue \land
  \# witnessEntry < \# segs \land
  (\forall i : 1 \upto \# witnessEntry @ Stringify(witnessEntry(i)) = segs(i))
  \THEN ztrue \ELSE zfalse)
\end{schema}

\begin{schema}{Init}
FileSegs'
\end{schema}

\begin{schema}{Idle}
\Xi FileSegs
\where
\lnot (semanticCovered = ztrue \land literalCovered = zfalse)
\end{schema}

\end{document}

